360				continue
361			}
362	
363			// File is in HEAD — compare content with working tree
364			absPath := filepath.Join(repoRoot, relPath)
365			workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
366			if err != nil {
367				// Can't read working tree file (deleted?) — keep it
368				result = append(result, relPath)
369				continue
370			}
371	
372			headContent, err := headFile.Contents()
373			if err != nil {
374				result = append(result, relPath)
375				continue
376			}
377	
378			if string(workingContent) != headContent {
379				// Working tree differs from HEAD — uncommitted changes
380				result = append(result, relPath)
381			}
382			// else: content matches HEAD — already committed, skip
383		}
